import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at register time when the inputSchema is uncompilable and the message names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken', description: 'broken tool', inputSchema: {type: 'not-a-real-type'}},
        async () => 'x'
      )
    ).toThrow(/broken/);
  });

  it('passes valid input through unchanged to executor exactly once', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const receivedInputs: Record<string, unknown>[] = [];

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {required_field: {type: 'string'}},
          required: ['required_field'],
        },
      },
      async input => {
        executorCalls += 1;
        receivedInputs.push(input);
        return 'success';
      }
    );

    const validInput = {required_field: 'value', extra_property: 'should pass through'};
    const response = await registry.execute('test_tool', validInput);

    expect({
      executorCalls,
      response,
      receivedInputsExactly: receivedInputs,
    }).toEqual({
      executorCalls: 1,
      response: {result: 'success'},
      receivedInputsExactly: [validInput],
    });
  });
});

